l":"https://res.cloudinary.com/dyqdfbaln/image/upload/v1792652433/naima-gazelle_owuppr.png","catalog_note":null},{"order":18,"artwork_code":"WR-018","title_ar":"رحلة","width_cm":77,"height_cm":176,"collection_kind":"painting","photo_url":"https://res.cloudinary.com/dyqdfbaln/image/upload/v1792652425/journey_ceb1qe.png","catalog_note":null},{"order":19,"artwork_code":"WR-019","title_ar":"بيتنا بالمجر","width_cm":85,"height_cm":216,"collection_kind":"painting","photo_url":"https://res.cloudinary.com/dyqdfbaln/image/upload/v1792652335/our-home-al-majar_gotr8a.png","catalog_note":null},{"order":20,"artwork_code":"WR-020","title_ar":"انتظار","width_cm":75,"height_cm":195,"collection_kind":"painting","photo_url":"https://res.cloudinary.com/dyqdfbaln/image/upload/v1792652436/waiting_soqbrc.png","catalog_note":null},{"order":21,"artwork_code":"WR-021","title_ar":"بالباب نعيمة","width_cm":65,"height_cm":176,"collection_kind":"painting","photo_url":"https://res.cloudinary.com/dyqdfbaln/image/upload/v1792652434/naima-at-door_xakvhl.png","catalog_note":null},{"order":22,"artwork_code":"WR-022","title_ar":"بنات الجيران","width_cm":217,"height_cm":167,"collection_kind":"painting","photo_url":null,"catalog_note":null},{"order":23,"artwork_code":"WR-023","title_ar":"نعيمة على بساط الريح","width_cm":215,"height_cm":175,"collection_kind":"painting","photo_url":null,"catalog_note":null},{"order":24,"artwork_code":"WR-024","title_ar":"حفلة عرس","width_cm":185,"height_cm":65,"collection_kind":"painting","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-001","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-002","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-003","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-004","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-005","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-006","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-007","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-008","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-009","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-010","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-011","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-012","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-013","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-014","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-015","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-016","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-017","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-018","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-019","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-020","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-021","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-022","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null},{"artwork_code":"MIN-023","title_ar":null,"width_cm":null,"height_cm":null,"collection_kind":"miniature","photo_url":null,"catalog_note":null}]$rows$::jsonb) loop
  pubid:=case when item->>'photo_url' is not null then regexp_replace(split_part(item->>'photo_url','/image/upload/',2),'^v[0-9]+/','') else null end;
  -- Match existing identity by supplied code, artist/title, or exact Cloudinary asset.
  select array_agg(distinct a.id) into matches from public.artworks a join public.exhibition_artworks ea on ea.artwork_id=a.id where ea.exhibition_id=target and (abaad_private.sales_normalize(ea.artwork_code)=abaad_private.sales_normalize(item->>'artwork_code') or (a.artist_id=artist and ((item->>'title_ar' is not null and abaad_private.sales_normalize(a.title_ar)=abaad_private.sales_normalize(item->>'title_ar')) or (pubid is not null and a.photo_public_id=pubid))));
  if coalesce(cardinality(matches),0)>1 then raise exception 'Ambiguous existing identity: %',item->>'artwork_code';end if;
  if cardinality(matches)=1 then
   person:=matches[1];
   if not exists(select 1 from public.artworks where id=person and artist_id=artist) or exists(select 1 from public.exhibition_artworks where artwork_id=person and exhibition_id<>target) then raise exception 'Artist or shared exhibition conflict: %',item->>'artwork_code';end if;
   if item->>'title_ar' is not null and exists(select 1 from public.artworks where id=person and abaad_private.sales_normalize(title_ar) is distinct from abaad_private.sales_normalize(item->>'title_ar') and photo_public_id is distinct from pubid) then raise exception 'Code belongs to another artwork: %',item->>'artwork_code';end if;
   if item->>'collection_kind'='painting' then
    update public.artworks a set width_cm=(item->>'width_cm')::numeric,height_cm=(item->>'height_cm')::numeric,collection_kind='painting',photo_url=coalesce(item->>'photo_url',a.photo_url),photo_public_id=coalesce(pubid,a.photo_public_id),photo_local_path=case when pubid is not null then null else a.photo_local_path end,catalog_note=item->>'catalog_note',updated_at=clock_timestamp()
    where id=person and (a.width_cm is distinct from (item->>'width_cm')::numeric or a.height_cm is distinct from (item->>'height_cm')::numeric or a.collection_kind is distinct from 'painting' or (pubid is not null and (a.photo_url is distinct from item->>'photo_url' or a.photo_public_id is distinct from pubid)) or a.catalog_note is distinct from item->>'catalog_note');
    if found then updated:=updated+1;update public.exhibition_artworks set version=version+1,updated_at=clock_timestamp() where artwork_id=person and exhibition_id=target;end if;
   else
    update public.artworks set collection_kind='miniature',updated_at=clock_timestamp() where id=person and collection_kind is distinct from 'miniature';
   end if;
   -- Never change listing ID, number, price, sale state, sale actors/times or history.
  else
   if item->>'title_ar' is not null and exists(select 1 from public.artworks a where a.artist_id=artist and (abaad_private.sales_normalize(a.title_ar)=abaad_private.sales_normalize(item->>'title_ar') or (pubid is not null and a.photo_public_id=pubid))) then raise exception 'Unlinked existing artwork requires identity review: %',item->>'artwork_code';end if;
   insert into public.artworks(artist_id,title_ar,width_cm,height_cm,photo_url,photo_public_id,collection_kind,catalog_note) values(artist,item->>'title_ar',(item->>'width_cm')::numeric,(item->>'height_cm')::numeric,item->>'photo_url',pubid,item->>'collection_kind',item->>'catalog_note') returning id into person;
   insert into public.exhibition_artworks(exhibition_id,artwork_id,artwork_code,price,currency,status) values(target,person,item->>'artwork_code',null,null,'not_for_sale');
   if item->>'collection_kind'='painting' then added_paintings:=added_paintings+1;else added_miniatures:=added_miniatures+1;end if;
  end if;
 end loop;
 if (select count(*) from public.exhibition_artworks ea join public.artworks a on a.id=ea.artwork_id where ea.exhibition_id=target and a.artist_id=artist)<>47 or (select count(*) from public.exhibition_artworks ea join public.artworks a on a.id=ea.artwork_id where ea.exhibition_id=target and a.artist_id=artist and a.collection_kind='painting')<>24 then raise exception 'Catalog count conflict: review existing works without deleting them';end if;
 raise notice 'Existing paintings updated %, new paintings %, new miniatures %',updated,added_paintings,added_miniatures;
end $seed$;
commit;
